package com.fabrizioroot.vertal.controller;
import com.fabrizioroot.vertal.dto.*; import com.fabrizioroot.vertal.service.TeamService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/teams") public class TeamController { private final TeamService teams; public TeamController(TeamService t){teams=t;}
 @PostMapping public TeamResponseDto create(@AuthenticationPrincipal Long uid,@Valid @RequestBody TeamRequestDto dto){return teams.create(uid,dto);} @GetMapping public List<TeamResponseDto> list(@AuthenticationPrincipal Long uid){return teams.list(uid);} @GetMapping("/{id}") public TeamResponseDto get(@AuthenticationPrincipal Long uid,@PathVariable Long id){return teams.get(uid,id);} @PostMapping("/{id}/members") public void add(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody MemberRequestDto dto){teams.add(uid,id,dto);} @DeleteMapping("/{id}/members/{username}") public void remove(@AuthenticationPrincipal Long uid,@PathVariable Long id,@PathVariable String username){teams.remove(uid,id,username);}
}